generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

model User {
  id        String    @id @default(cuid())
  email     String    @unique
  name      String?
  tasks     Task[]
  projects  Project[]
}

model Project {
  id          Int     @id @default(autoincrement())
  name        String
  description String?
  ownerId     String
  owner       User    @relation(fields: [ownerId], references: [id])
  tasks       Task[]
  createdAt   DateTime @default(now())
}

model Task {
  id          Int      @id @default(autoincrement())
  title       String
  completed   Boolean  @default(false)
  assigneeId  String?
  projectId   Int
  assignee    User?    @relation(fields: [assigneeId], references: [id])
  project     Project  @relation(fields: [projectId], references: [id])
  createdAt   DateTime @default(now())
}

'use server';

import prisma from '@/lib/prisma';
import { auth } from '@/auth';
import { revalidateTag } from 'next/cache';

export async function createTask(formData: FormData) {
  const session = await auth();
  if (!session?.user) throw new Error('Unauthorized');

  const title = formData.get('title') as string;
  const projectId = parseInt(formData.get('projectId') as string);

  const task = await prisma.task.create({
    data: { title, projectId, assigneeId: session.user.id }
  });

  revalidateTag('tasks');
  return task;
}

export async function toggleTask(id: number) {
  const task = await prisma.task.findUnique({ where: { id } });
  if (!task) throw new Error('Task not found');

  return prisma.task.update({
    where: { id },
    data: { completed: !task.completed }
  });
}

export async function deleteTask(id: number) {
  await prisma.task.delete({ where: { id } });
  revalidateTag('tasks');
}

import prisma from '@/lib/prisma';

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const projectId = parseInt(searchParams.get('projectId') || '0');

  const tasks = await prisma.task.findMany({
    where: { projectId },
    include: { assignee: true },
    orderBy: { createdAt: 'desc' }
  });

  return Response.json(tasks);
}

'use client';

import { createTask, toggleTask, deleteTask } from '@/app/actions';
import useSWR from 'swr';

const fetcher = (url: string) => fetch(url).then(r => r.json());

export function TaskList({ projectId }: { projectId: number }) {
  const { data: tasks, mutate } = useSWR(
    `/api/tasks?projectId=${projectId}`,
    fetcher
  );

  async function handleCreate(formData: FormData) {
    await createTask(formData);
    mutate();
  }

  return (
    <div>
      <form action={handleCreate}>
        <input name="title" required />
        <input type="hidden" name="projectId" value={projectId} />
        <button type="submit">Add Task</button>
      </form>
      <ul>
        {tasks?.map((task) => (
          <li key={task.id}>
            <input
              type="checkbox"
              checked={task.completed}
              onChange={() => toggleTask(task.id)}
            />
            <span>{task.title}</span>
            <button onClick={() => deleteTask(task.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}
